<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pageTitle='Início';$cid=current_user()['id'];$pdo=db();$count=$pdo->prepare('SELECT COUNT(*) FROM encomendas WHERE cliente_id=?');$count->execute([$cid]);$totalOrders=(int)$count->fetchColumn();$pending=$pdo->prepare("SELECT COUNT(*) FROM encomendas WHERE cliente_id=? AND status NOT IN ('Entregue','Cancelada')");$pending->execute([$cid]);$pending=(int)$pending->fetchColumn();$last=$pdo->prepare('SELECT * FROM encomendas WHERE cliente_id=? ORDER BY id DESC LIMIT 5');$last->execute([$cid]);$rows=$last->fetchAll();include __DIR__.'/../includes/header.php'; ?><div class="page-head"><div><h1>Olá, <?=e(current_user()['name'])?></h1><div class="muted">Acompanhe suas encomendas e faça novos pedidos.</div></div><a class="btn primary" href="nova-encomenda.php">＋ Nova encomenda</a></div><div class="dashboard-grid"><div class="card stat"><span class="label">Minhas encomendas</span><span class="value"><?=$totalOrders?></span></div><div class="card stat"><span class="label">Em andamento</span><span class="value"><?=$pending?></span></div></div><div class="card" style="margin-top:16px"><h3>Últimas encomendas</h3><div class="table-wrap"><table class="table"><thead><tr><th>Número</th><th>Data</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['numero'])?></td><td><?=datetime_br($r['data_hora'])?></td><td><?=status_badge($r['status'])?></td><td><?=money($r['total'])?></td><td><a class="btn small secondary" href="encomenda.php?id=<?=$r['id']?>">Detalhes</a></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="5" class="empty">Você ainda não possui encomendas.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
